import{_ as e,o as a,c as r,a2 as s}from"./chunks/framework.DDY-poMm.js";const u=JSON.parse('{"title":"Features","description":"","frontmatter":{},"headers":[],"relativePath":"intro/features.md","filePath":"intro/features.md","lastUpdated":1790683574000}'),d={name:"intro/features.md"};function n(o,t,i,l,c,h){return a(),r("div",null,[...t[0]||(t[0]=[s('<h1 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h1><p>This page lists the modules the system <strong>actually has</strong>. Whether each module is open to end users is controlled by operators through feature configuration in the admin console.</p><h2 id="trading" tabindex="-1">Trading <a class="header-anchor" href="#trading" aria-label="Permalink to &quot;Trading&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Product</th><th>Description</th></tr></thead><tbody><tr><td>Spot</td><td>Coin-to-coin trading with limit and market orders</td></tr><tr><td>Instant swap</td><td>Convert directly between two assets at the current price, no order book needed</td></tr><tr><td>Seconds contracts</td><td>Short-term up/down predictions, settled on the outcome at expiry</td></tr><tr><td>USDT-margined perpetuals</td><td>Leveraged long/short trading with take-profit, stop-loss and forced liquidation</td></tr><tr><td>TradFi</td><td>Market data and trading for forex, commodities, stocks, indices, Hong Kong equities and more</td></tr><tr><td>Copy trading</td><td>Lead traders issue a code; users follow with one tap using the code. See <a href="/CoinExchange/guide/follow">Copy Trading</a></td></tr></tbody></table><h2 id="wealth-and-value-added-products" tabindex="-1">Wealth and value-added products <a class="header-anchor" href="#wealth-and-value-added-products" aria-label="Permalink to &quot;Wealth and value-added products&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Module</th><th>Description</th></tr></thead><tbody><tr><td>Wealth management</td><td>Asset management products that accrue interest by term</td></tr><tr><td>Staking</td><td>Lock assets to earn rewards</td></tr><tr><td>Assisted lending</td><td>Lending-style product</td></tr><tr><td>Token subscription (IPO)</td><td>New coin subscriptions, with stages from preparation, subscription and approval to live and issued</td></tr><tr><td>Platform tokens &amp; market making</td><td>The platform can issue its own tokens and assign them to designated market maker accounts; platform tokens can also be used to pay trading fees. See <a href="/CoinExchange/guide/market-maker">Market Maker Portal</a></td></tr></tbody></table><h2 id="funds" tabindex="-1">Funds <a class="header-anchor" href="#funds" aria-label="Permalink to &quot;Funds&quot;">​</a></h2><ul><li><strong>Deposits</strong>: digital asset deposits; each user has a dedicated receiving address, credited automatically once received on-chain</li><li><strong>Withdrawals</strong>: withdrawal requests with admin review, configurable withdrawal channels and limits</li><li><strong>Transfers</strong>: move assets between the different funding accounts of a user</li><li><strong>Ledger</strong>: a complete record of every movement of funds</li></ul><p>See <a href="/CoinExchange/guide/finance">Deposits &amp; Withdrawals</a>.</p><h2 id="users-and-operations" tabindex="-1">Users and operations <a class="header-anchor" href="#users-and-operations" aria-label="Permalink to &quot;Users and operations&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Module</th><th>Description</th></tr></thead><tbody><tr><td>User management</td><td>Profiles, account status, credit score</td></tr><tr><td>KYC</td><td>Basic and advanced verification with admin review</td></tr><tr><td>VIP tiers</td><td>Tier thresholds and benefit descriptions are configurable in the admin console</td></tr><tr><td>Referral &amp; agents</td><td>Invitation codes, referral relationships, commissions</td></tr><tr><td>Geo-restrictions</td><td>Restrict access by region</td></tr><tr><td>Help center &amp; announcements</td><td>Content maintained in the admin console</td></tr><tr><td>In-app messages</td><td>Send messages from the admin console to specific users or everyone; users read them in the message center of the app / website</td></tr><tr><td>Open API (API Key)</td><td>Issue credentials for external systems to call market data and open APIs, with rate limits and IP allowlists</td></tr><tr><td>Live chat</td><td>Users chat directly inside the app / mobile site; agents reply from a Telegram topic group — one conversation per user, text and images in real time. See <a href="/CoinExchange/guide/customer-service">Customer Service</a></td></tr></tbody></table><h2 id="languages" tabindex="-1">Languages <a class="header-anchor" href="#languages" aria-label="Permalink to &quot;Languages&quot;">​</a></h2><p>The user side supports <strong>7 languages</strong>: Simplified Chinese, Traditional Chinese, English, Japanese, Korean, Vietnamese and Thai. Which ones are enabled is controlled by the language dictionary in the admin console.</p><h2 id="mobile-app" tabindex="-1">Mobile app <a class="header-anchor" href="#mobile-app" aria-label="Permalink to &quot;Mobile app&quot;">​</a></h2><p>A <strong>native dual-platform app (Android / iOS)</strong>, not a web wrapper. Features match the H5 site, with <strong>automatic new-version detection and update prompts</strong>; on Android the download and installation can be completed inside the app. See <a href="/CoinExchange/app/overview">Mobile App</a>.</p><hr><div class="tip custom-block"><p class="custom-block-title">Note</p><p>This page lists implemented features only. Specific business rules for each feature (fees, settlement basis, risk parameters, etc.) are configured by operators in the admin console — refer to the actual configuration of your own console.</p></div>',17)])])}const m=e(d,[["render",n]]);export{u as __pageData,m as default};
